pow_body:
pub fn pow(&self, by: &[u64; 4]) -> Self {
    let mut res = Self::one();
    for e in by.iter().rev() {
        for i in (0..64).rev() {
            res = res.square();
            let mut tmp = res;
            tmp *= self;
            res.conditional_assign(&tmp, (((*e >> i) & 0x1) as u8).into());
        }
    }
    res
}

