pub fn pow_vartime(&self, by: &[u64; 4]) -> Self {
    let mut res = Self::one();
    for e in by.iter().rev() {
        for i in (0..64).rev() {
            res = res.square();

            if ((*e >> i) & 1) == 1 {
                res.mul_assign(self);
            }
        }
    }
    res
}

